export function icon(name, size = 16, extraClass = "") {
  const wrapper = document.createElement("span");
  wrapper.className = `icon ${extraClass}`.trim();
  wrapper.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] || ICONS.info}</svg>`;
  return wrapper;
}
